-- ===========================================================================
-- Payslips: each person's salary slip, issued from the approved payroll.
--
-- Salary is paid at the end of the month. The executive approves the month's
-- payroll around the 25th; at the month's release moment -- by default the
-- last day of the month at 23:59 WIB -- every line on that approved run gets
-- a slip, which its owner then finds under My Profile. The director can move
-- the release moment (day of month and time) or switch automatic release off
-- in Settings, and can issue a month's slips at once from the Payroll page.
--
-- A slip is a snapshot: `data` holds every figure and label the PDF shows,
-- worked out here from the payroll line with the payroll area's own
-- arithmetic (payroll_line_figures), and rounded to the rupiah. The browser
-- only lays it out onto the company template (src/lib/payslipPdf.ts).
--
-- A month that is sent back after approval hides its slips from staff until
-- it is approved again; the slips are then rebuilt at the next run after the
-- release moment. A slip counts as current when it was generated at or after
-- the month's latest approval.
--
-- Who may see slips: the owner (their own, while the month stands approved),
-- and the payroll viewers -- finance, the director and the executive.
-- ===========================================================================

begin;

-- ---------------------------------------------------------------------------
-- 1. Tables.
-- ---------------------------------------------------------------------------

-- The blank company template: the August 2026 sample with the variable text
-- removed. It carries Peter's signature and the company stamp, so it lives
-- here behind payslips_template() rather than as a public web asset.
create table if not exists public.payslip_template (
    id         int primary key check (id = 1),
    pdf        bytea not null,
    updated_at timestamptz not null default now()
);

create table if not exists public.payslip_settings (
    id            int primary key default 1 check (id = 1),
    auto_enabled  boolean not null default true,
    -- Null is the last day of the month. A day past the month's end means
    -- the last day (31 in September is the 30th).
    release_day   int check (release_day between 1 and 31),
    release_time  time not null default '23:59',
    -- Automatic release covers payroll months from this one on. Earlier
    -- months were paid before slips existed and are not sent to everybody.
    start_month   date not null default '2026-09-01',
    updated_at    timestamptz not null default now(),
    updated_by_id uuid references public.users(id) on delete set null
);
insert into public.payslip_settings (id) values (1) on conflict (id) do nothing;

create table if not exists public.payslips (
    id              uuid primary key default gen_random_uuid(),
    month_id        uuid not null references public.payroll_months(id) on delete cascade,
    payroll_line_id uuid not null references public.payroll_lines(id) on delete cascade,
    -- Nullable: the payroll sheet carries people with no staff record.
    employee_id     uuid references public.employees(id) on delete set null,
    year            int not null,
    month           int not null,
    issue_date      date not null,
    data            jsonb not null,
    generated_at    timestamptz not null default now(),
    -- Null when the schedule issued it.
    generated_by_id uuid references public.users(id) on delete set null,
    constraint uq_payslip_month_line unique (month_id, payroll_line_id)
);
create index if not exists ix_payslips_employee_id on public.payslips (employee_id);
create index if not exists ix_payslips_month_id    on public.payslips (month_id);

alter table public.payslip_template enable row level security;
alter table public.payslip_settings enable row level security;
alter table public.payslips         enable row level security;

