-- ---------------------------------------------------------------------------
-- 2. Internal helpers.
-- ---------------------------------------------------------------------------

-- Finance, the director and the executive: the payroll area's readers.
create or replace function public.payslips_is_viewer()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
    select public.is_active_user()
       and coalesce(public.current_user_role()::text, '') in ('finance', 'director', 'executive');
$$;

-- The moment a month's slips are released: the set day (clamped to the
-- month's last day; null is the last day) at the set time, in Jakarta.
create or replace function public.payslips_release_at(p_year int, p_month int)
returns timestamptz
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    s public.payslip_settings;
    last_day int := public.payroll_days_in_month(p_year, p_month);
begin
    select * into s from public.payslip_settings where id = 1;
    return (make_date(p_year, p_month, least(coalesce(s.release_day, last_day), last_day))
            + coalesce(s.release_time, time '23:59')) at time zone 'Asia/Jakarta';
end;
$$;

-- A count as the slip shows it: 1, 12, 22/31, 1.5.
create or replace function public.payslips_count_text(p double precision)
returns text
language sql
immutable
set search_path = public, pg_temp
as $$
    select case when p is null then ''
                when p = trunc(p) then trunc(p)::bigint::text
                else rtrim(rtrim(round(p::numeric, 2)::text, '0'), '.') end;
$$;

-- Whole rupiah, half-up.
create or replace function public.payslips_rupiah(p double precision)
returns bigint
language sql
immutable
set search_path = public, pg_temp
as $$
    select round(coalesce(p, 0)::numeric)::bigint;
$$;

-- Whether a slip is current: its month approved, and the slip built from
-- that approval rather than an earlier one.
create or replace function public.payslips_current(s public.payslips, m public.payroll_months)
returns boolean
language sql
immutable
set search_path = public, pg_temp
as $$
    select m.status = 'approved' and s.generated_at >= coalesce(m.approved_at, '-infinity'::timestamptz);
$$;

-- Everything the PDF shows for one payroll line, worked out and rounded.
create or replace function public.payslips_line_data(p_line_id uuid, p_issue_date date)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    l public.payroll_lines;
    m public.payroll_months;
    days int;
    f jsonb;
    v_first text;
    label text;
    divisor double precision;
    base_amt bigint;   base_rate bigint;   base_unit text;
    health bigint;     resp bigint;
    shift_amt bigint;  shift_rate bigint;  shift_unit text;
    overtime bigint;
    bpjs_e bigint;     bpjs_h bigint;      tax bigint;
    others bigint;
    total_e bigint;    total_d bigint;
begin
    select * into l from public.payroll_lines where id = p_line_id;
    select * into m from public.payroll_months where id = l.month_id;
    days := public.payroll_days_in_month(m.year, m.month);
    f := public.payroll_line_figures(l, days);
    label := public.payroll_label(m.year, m.month);

    base_amt := public.payslips_rupiah((f ->> 'base_paid')::float8);
    base_rate := public.payslips_rupiah(l.base);
    if l.part_days is null then
        base_unit := '1';
    else
        divisor := case when coalesce(l.part_divisor, 0) <> 0 then l.part_divisor
                        else days::double precision end;
        base_unit := public.payslips_count_text(l.part_days) || '/' || public.payslips_count_text(divisor);
    end if;
    if base_amt = 0 then
        base_rate := 0;
        base_unit := '0';
    end if;

    health := public.payslips_rupiah(l.health_allowance);
    resp := public.payslips_rupiah(l.responsibility_allowance);

    shift_amt := public.payslips_rupiah((f ->> 'total_shift_allowance')::float8);
    shift_rate := public.payslips_rupiah(l.shift_allowance_rate);
    shift_unit := public.payslips_count_text(l.shift_days);
    if shift_amt = 0 then
        shift_rate := 0;
        shift_unit := '0';
    end if;

    overtime := public.payslips_rupiah(l.overtime_allowance);
    bpjs_e := public.payslips_rupiah(l.bpjs_employment);
    bpjs_h := public.payslips_rupiah(l.bpjs_health);
    tax := public.payslips_rupiah(l.income_tax);
    -- Public holiday pay and the one-offs (THR, bonus) have no row of their own.
    others := public.payslips_rupiah((f ->> 'public_holiday_allowance')::float8 + l.bonus_other);

    total_e := base_amt + health + resp + shift_amt + overtime + bpjs_e + bpjs_h + tax + others;
    total_d := bpjs_e + bpjs_h + tax;

    if l.employee_id is not null then
        select nullif(btrim(e.first_name), '') into v_first from public.employees e where e.id = l.employee_id;
    end if;
    v_first := initcap(split_part(btrim(coalesce(v_first, l.person_name)), ' ', 1));

    return jsonb_build_object(
        'period_label', label,
        'year', m.year,
        'month', m.month,
        'issue_date', to_char(p_issue_date, 'YYYY-MM-DD'),
        'person_name', upper(btrim(l.person_name)),
        'first_name', v_first,
        'position', upper(btrim(coalesce(l.position, ''))),
        'tax_bearer', btrim(coalesce(l.ptkp_status, '')),
        'file_name', 'Payslip ' || label || ' - ' || v_first || '.pdf',
        'earnings', jsonb_build_object(
            'base', jsonb_build_object('rate', base_rate, 'unit', base_unit, 'amount', base_amt),
            'health', jsonb_build_object('rate', health, 'unit', case when health = 0 then '0' else '1' end, 'amount', health),
            'responsibility', jsonb_build_object('rate', resp, 'unit', case when resp = 0 then '0' else '1' end, 'amount', resp),
            'shift', jsonb_build_object('rate', shift_rate, 'unit', shift_unit, 'amount', shift_amt),
            'overtime', jsonb_build_object('rate', overtime, 'unit', case when overtime = 0 then '0' else '1' end, 'amount', overtime),
            'bpjs_employment', bpjs_e,
            'bpjs_health', bpjs_h,
            'income_tax', tax,
            'others', others),
        'deductions', jsonb_build_object(
            'bpjs_employment', bpjs_e,
            'bpjs_health', bpjs_h,
            'income_tax', tax),
        'total_earnings', total_e,
        'total_deductions', total_d,
        'net_pay', total_e - total_d
    );
end;
$$;

-- Build or rebuild the slips of an approved month: every line, or only one
-- employee's. Returns how many were written. Called by the schedule, by
-- payslips_issue_now() and by the backfill below; never by a client.
create or replace function public.payslips_issue_month(
    p_month_id uuid,
    p_employee_id uuid default null,
    p_actor uuid default null
)
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    m public.payroll_months;
    v_issue date;
    l record;
    n int := 0;
begin
    select * into m from public.payroll_months where id = p_month_id;
    if not found then
        raise exception 'Not found' using errcode = 'PT404';
    end if;
    if m.status <> 'approved' then
        raise exception 'Only an approved payroll month has payslips.' using errcode = 'PT409';
    end if;
    v_issue := (public.payslips_release_at(m.year, m.month) at time zone 'Asia/Jakarta')::date;

    for l in
        select id, employee_id from public.payroll_lines
         where month_id = m.id
           and (p_employee_id is null or employee_id = p_employee_id)
    loop
        insert into public.payslips (month_id, payroll_line_id, employee_id, year, month,
                                     issue_date, data, generated_at, generated_by_id)
        values (m.id, l.id, l.employee_id, m.year, m.month,
                v_issue, public.payslips_line_data(l.id, v_issue), now(), p_actor)
        on conflict (month_id, payroll_line_id) do update
           set employee_id = excluded.employee_id,
               year = excluded.year,
               month = excluded.month,
               issue_date = excluded.issue_date,
               data = excluded.data,
               generated_at = excluded.generated_at,
               generated_by_id = excluded.generated_by_id;
        n := n + 1;
    end loop;
    return n;
end;
$$;

-- The scheduled run. Every approved month from the start month on whose
-- release moment has passed gets its slips, unless every line already has a
-- slip built since the month's latest approval. Returns slips written.
create or replace function public.payslips_generate_due(p_now timestamptz default now())
returns int
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    s public.payslip_settings;
    m public.payroll_months;
    n int := 0;
begin
    select * into s from public.payslip_settings where id = 1;
    if not found or not s.auto_enabled then
        return 0;
    end if;
    for m in
        select * from public.payroll_months
         where status = 'approved'
           and make_date(year, month, 1) >= s.start_month
         order by year, month
    loop
        if public.payslips_release_at(m.year, m.month) > p_now then
            continue;
        end if;
        if exists (
            select 1 from public.payroll_lines l
             where l.month_id = m.id
               and not exists (
                   select 1 from public.payslips p
                    where p.payroll_line_id = l.id
                      and p.generated_at >= coalesce(m.approved_at, '-infinity'::timestamptz)))
        then
            n := n + public.payslips_issue_month(m.id, null, null);
        end if;
    end loop;
    return n;
end;
$$;

-- The settings as the screens read them, with when the next slips go out.
create or replace function public.payslips_settings_json()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    s public.payslip_settings;
    today date := public.local_today();
    y int := extract(year from today)::int;
    mo int := extract(month from today)::int;
    ra timestamptz;
begin
    select * into s from public.payslip_settings where id = 1;
    ra := public.payslips_release_at(y, mo);
    if ra <= now() then
        mo := mo + 1;
        if mo = 13 then
            mo := 1;
            y := y + 1;
        end if;
        ra := public.payslips_release_at(y, mo);
    end if;
    return jsonb_build_object(
        'auto_enabled', s.auto_enabled,
        'release_day', s.release_day,
        'release_time', to_char(s.release_time, 'HH24:MI'),
        'start_month', to_char(s.start_month, 'YYYY-MM-DD'),
        'updated_at', s.updated_at,
        'next_release', jsonb_build_object(
            'year', y,
            'month', mo,
            'label', public.payroll_label(y, mo),
            'release_at', ra)
    );
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. What the screens call.
-- ---------------------------------------------------------------------------

-- My Profile: the caller's own slips, for months that stand approved.
create or replace function public.payslips_mine()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    emp uuid := public.current_employee_id();
begin
    if auth.uid() is null or not public.is_active_user() or emp is null then
        return '[]'::jsonb;
    end if;
    return coalesce((
        select jsonb_agg(jsonb_build_object(
                   'id', s.id,
                   'year', s.year,
                   'month', s.month,
                   'label', public.payroll_label(s.year, s.month),
                   'issue_date', to_char(s.issue_date, 'YYYY-MM-DD'),
                   'net_pay', (s.data ->> 'net_pay')::bigint,
                   'file_name', s.data ->> 'file_name')
                 order by s.year desc, s.month desc)
          from public.payslips s
          join public.payroll_months m on m.id = s.month_id
         where s.employee_id = emp
           and public.payslips_current(s, m)), '[]'::jsonb);
end;
$$;

-- One slip, with everything the PDF needs. The owner, or a payroll viewer.
create or replace function public.payslips_get(p_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    s public.payslips;
    m public.payroll_months;
begin
    select * into s from public.payslips where id = p_id;
    if found then
        select * into m from public.payroll_months where id = s.month_id;
    end if;
    if not found
       or not (public.payslips_is_viewer()
               or (public.is_active_user()
                   and s.employee_id is not null
                   and s.employee_id = public.current_employee_id()
                   and public.payslips_current(s, m))) then
        raise exception 'Not found' using errcode = 'PT404';
    end if;
    return jsonb_build_object(
        'id', s.id,
        'year', s.year,
        'month', s.month,
        'issue_date', to_char(s.issue_date, 'YYYY-MM-DD'),
        'data', s.data);
end;
$$;

-- The Payroll page's line about one month's slips, and the slips themselves.
create or replace function public.payslips_for_month(p_month_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    m public.payroll_months;
    st public.payslip_settings;
    v_slips jsonb;
    v_issue date;
begin
    if not public.payslips_is_viewer() then
        raise exception 'Not found' using errcode = 'PT404';
    end if;
    m := public.payroll_load_month(p_month_id);
    select * into st from public.payslip_settings where id = 1;

    select coalesce(jsonb_agg(jsonb_build_object(
                'id', s.id,
                'person_name', s.data ->> 'person_name',
                'employee_id', s.employee_id,
                'file_name', s.data ->> 'file_name')
              order by (l.labour_group <> 'service'), l.row_no, l.created_at, l.id), '[]'::jsonb),
           max(s.issue_date)
      into v_slips, v_issue
      from public.payslips s
      join public.payroll_lines l on l.id = s.payroll_line_id
     where s.month_id = m.id
       and public.payslips_current(s, m);

    return jsonb_build_object(
        'month_id', m.id,
        'status', m.status,
        'release_at', public.payslips_release_at(m.year, m.month),
        'automatic', st.auto_enabled and make_date(m.year, m.month, 1) >= st.start_month,
        'issued', jsonb_array_length(v_slips) > 0,
        'issue_date', to_char(v_issue, 'YYYY-MM-DD'),
        'slips', v_slips);
end;
$$;

-- The director issues (or re-issues) a month's slips now, whatever the time.
create or replace function public.payslips_issue_now(p_month_id uuid, p_employee_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    m public.payroll_months;
    n int;
begin
    if not public.is_platform_admin() then
        raise exception 'Only the director can issue payslips.' using errcode = 'PT403';
    end if;
    m := public.payroll_load_month(p_month_id);
    n := public.payslips_issue_month(m.id, p_employee_id, auth.uid());
    perform public.log_activity('PAYSLIPS_ISSUED',
        'Issued ' || n || case when n = 1 then ' payslip' else ' payslips' end
        || ' for ' || public.payroll_label(m.year, m.month),
        m.id);
    return public.payslips_for_month(m.id);
end;
$$;

create or replace function public.payslips_settings_get()
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
    if not (public.payslips_is_viewer() or public.is_platform_admin()) then
        raise exception 'Not found' using errcode = 'PT404';
    end if;
    return public.payslips_settings_json();
end;
$$;

create or replace function public.payslips_settings_update(p_changes jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
    p jsonb := coalesce(p_changes, '{}'::jsonb);
    k text;
    v_day int;
    v_time time;
begin
    if not public.is_platform_admin() then
        raise exception 'Only the director can change when payslips are released.' using errcode = 'PT403';
    end if;
    for k in select jsonb_object_keys(p) loop
        if k not in ('auto_enabled', 'release_day', 'release_time') then
            raise exception 'Unknown field: %', k using errcode = 'PT422';
        end if;
    end loop;
    if p ? 'auto_enabled' and jsonb_typeof(p -> 'auto_enabled') <> 'boolean' then
        raise exception 'auto_enabled must be true or false' using errcode = 'PT422';
    end if;
    if p ? 'release_day' and jsonb_typeof(p -> 'release_day') <> 'null' then
        if jsonb_typeof(p -> 'release_day') <> 'number'
           or (p ->> 'release_day')::numeric <> trunc((p ->> 'release_day')::numeric)
           or (p ->> 'release_day')::numeric not between 1 and 31 then
            raise exception 'The release day must be a day from 1 to 31, or the last day of the month.'
                using errcode = 'PT422';
        end if;
        v_day := (p ->> 'release_day')::int;
    end if;
    if p ? 'release_time' then
        if coalesce(p ->> 'release_time', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9](:[0-5][0-9])?$' then
            raise exception 'The release time must be a time of day, such as 23:59.' using errcode = 'PT422';
        end if;
        v_time := (p ->> 'release_time')::time;
    end if;

    update public.payslip_settings set
        auto_enabled = case when p ? 'auto_enabled' then (p ->> 'auto_enabled')::boolean else auto_enabled end,
        release_day = case when p ? 'release_day' then v_day else release_day end,
        release_time = case when p ? 'release_time' then v_time else release_time end,
        updated_at = now(),
        updated_by_id = auth.uid()
    where id = 1;

    perform public.log_activity('PAYSLIP_SETTINGS_UPDATED', 'Changed when payslips are released');
    return public.payslips_settings_json();
end;
$$;

-- The blank template, base64, for a signed-in user who may see a slip.
create or replace function public.payslips_template()
returns text
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
    emp uuid := public.current_employee_id();
begin
    if auth.uid() is null or not public.is_active_user() then
        raise exception 'Not found' using errcode = 'PT404';
    end if;
    if not public.payslips_is_viewer()
       and not (emp is not null and exists (
                select 1 from public.payslips s
                  join public.payroll_months m on m.id = s.month_id
                 where s.employee_id = emp and public.payslips_current(s, m))) then
        raise exception 'Not found' using errcode = 'PT404';
    end if;
    return (select translate(encode(pdf, 'base64'), E'\n\r', '') from public.payslip_template where id = 1);
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Grants.
-- ---------------------------------------------------------------------------
do $$
declare
    f text;
begin
    foreach f in array array[
        'public.payslips_is_viewer()',
        'public.payslips_release_at(int, int)',
        'public.payslips_count_text(double precision)',
        'public.payslips_rupiah(double precision)',
        'public.payslips_current(public.payslips, public.payroll_months)',
        'public.payslips_line_data(uuid, date)',
        'public.payslips_issue_month(uuid, uuid, uuid)',
        'public.payslips_generate_due(timestamptz)',
        'public.payslips_settings_json()'
    ] loop
        execute format('revoke all on function %s from public, anon, authenticated', f);
    end loop;

    foreach f in array array[
        'public.payslips_mine()',
        'public.payslips_get(uuid)',
        'public.payslips_for_month(uuid)',
        'public.payslips_issue_now(uuid, uuid)',
        'public.payslips_settings_get()',
        'public.payslips_settings_update(jsonb)',
        'public.payslips_template()'
    ] loop
        execute format('revoke all on function %s from public, anon', f);
        execute format('grant execute on function %s to authenticated', f);
    end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 5. One-off: Nurhuda's own slips for January to August 2026, so she can try
--    it on her account first. Each is dated its month's last day (the default
--    release day). September onwards is released by the schedule. Idempotent;
--    nothing happens where her record or those months are absent.
-- ---------------------------------------------------------------------------
do $$
declare
    emp uuid;
    r record;
begin
    select e.id into emp from public.employees e
     where lower(e.email) = 'nurhuda.santoso@dtgeotech.com'
     limit 1;
    if emp is null then
        return;
    end if;
    for r in
        select m.id from public.payroll_months m
         where m.year = 2026 and m.month between 1 and 8 and m.status = 'approved'
           and exists (select 1 from public.payroll_lines l
                        where l.month_id = m.id and l.employee_id = emp)
         order by m.month
    loop
        perform public.payslips_issue_month(r.id, emp, null);
    end loop;
end $$;

-- ---------------------------------------------------------------------------
-- 6. Schedule: release due slips every five minutes. Only where pg_cron
--    exists (the hosted database; not the PGlite test database).
-- ---------------------------------------------------------------------------
do $$
begin
    if exists (select 1 from pg_available_extensions where name = 'pg_cron') then
        begin
            create extension if not exists pg_cron;
        exception when others then
            raise notice 'payslips-release not scheduled: %', sqlerrm;
        end;
    end if;

    if exists (select 1 from pg_extension where extname = 'pg_cron') then
        perform cron.schedule(
            'payslips-release',
            '*/5 * * * *',
            $cron$select public.payslips_generate_due();$cron$);
    end if;
end
$$;

commit;
